cd /tmp && mkdir -p /tmp/render-check && cat > /tmp/render-check/render.mjs <<'EOF'
const { Dotprompt } = await import('node_modules/dotprompt/lib/index.mjs').catch(async () => import('node_modules/dotprompt/lib/index.js'));
import { readFileSync } from 'node:fs';
const src = readFileSync(process.argv[2], 'utf8');
const dp = new Dotprompt();
const rendered = await dp.render(src, { customerName: 'Ada' });
console.log(JSON.stringify(rendered.messages.map(m => m.content.map(c => c.text).join(''))));
EOF
